const cfg = {};
for (const i of $('Get Config').all()) cfg[String(i.json.key).trim()] = i.json.value;
const tz = cfg.timezone || 'Asia/Jakarta';
const nowDt = $now.setZone(tz);
const force = $('Tes Manual').isExecuted;   // true jika dijalankan dari trigger 'Tes Manual'
const norm = (v) => {
  if (v === undefined || v === null) return '';
  const m = String(v).trim().toUpperCase().replace('.', ':').match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/);
  if (!m) return '';
  let h = Number(m[1]);
  if (m[3] === 'PM' && h < 12) h += 12;
  if (m[3] === 'AM' && h === 12) h = 0;
  return String(h).padStart(2, '0') + ':' + m[2];
};
const msgs = $('Get Messages').all().map(i => i.json);
function pick(type) {
  const pool = msgs.filter(m => String(m.tipe).trim().toLowerCase() === type && String(m.teks || '').trim());
  if (!pool.length) return null;
  const w = pool.map(m => Math.max(Number(m.bobot) || 1, 0));
  const tot = w.reduce((a, b) => a + b, 0);
  let r = Math.random() * tot;
  for (let i = 0; i < pool.length; i++) { r -= w[i]; if (r <= 0) return pool[i].teks; }
  return pool[pool.length - 1].teks;
}
const min = Number(cfg.min_delay_sec) || 5;
const max = Math.max(Number(cfg.max_delay_sec) || 30, min);
const gnDefault = norm(cfg.gn_time) || '19:00';   // jam GN universal (isi key gn_time di Config untuk mengubah)
// satu pesan GM dan satu pesan GN dipilih sekali, dipakai sama untuk SEMUA channel
const textByType = { gm: pick('gm'), gn: pick('gn') };
const out = [];
const seen = new Set();
for (const item of $input.all()) {
  const c = item.json;
  const id = String(c.channel_id || '').trim();
  if (String(c.aktif).trim().toUpperCase() !== 'TRUE') continue;
  if (!/^\d{17,20}$/.test(id)) continue;
  if (seen.has(id)) continue;
  seen.add(id);
  for (const type of ['gm', 'gn']) {
    if (force && type !== 'gm') continue;
    let ts = nowDt.toMillis();                     // GM: dikirim saat workflow mulai
    if (type === 'gn') {
      const [h, m] = gnDefault.split(':').map(Number);
      ts = nowDt.set({ hour: h, minute: m, second: 0, millisecond: 0 }).toMillis();
      if (ts < nowDt.toMillis()) continue;         // jam GN hari ini sudah lewat: lewati
    }
    const text = textByType[type];
    out.push({ json: { channel_id: id, tipe: type, teks: text || '', ts,
      delay: text ? Math.floor(Math.random() * (max - min + 1)) + min : 0 } });
  }
}
out.sort((a, b) => a.json.ts - b.json.ts);   // semua GM dulu, lalu GN
return out;

const src = $('Wait Acak').item.json;
const ch = ($('Info Channel').item.json.body) || {};
const gd = ($('Info Server').item.json.body) || {};
const r = $json;
const ok = r.statusCode >= 200 && r.statusCode < 300;
const body = r.body || {};
return { json: {
  waktu: $now.toFormat('yyyy-MM-dd HH:mm:ss'),
  server: gd.name || '(server tidak diketahui)',
  nama_channel: ch.name ? '#' + ch.name : '(tidak diketahui)',
  channel_id: src.channel_id, tipe: src.tipe, pesan: src.teks,
  message_id: ok ? String(body.id || '') : '',
  status: ok ? 'TERKIRIM' : 'GAGAL',
  error: ok ? '' : (!src.teks ? ('Sheet Messages tidak punya pesan bertipe ' + src.tipe) : ('HTTP ' + r.statusCode + ': ' + JSON.stringify(body).slice(0, 200)))
}};

const logs = $input.all().map(i => i.json);
const cfg = {};
for (const i of $('Get Config').all()) cfg[String(i.json.key).trim()] = i.json.value;
const monitor = String(cfg.monitor_channel_id || '').replace(/\D/g, '');
const hook = String(cfg.monitor_webhook_url || '').trim();
const okHook = /^https:\/\/(?:ptb\.|canary\.)?discord(?:app)?\.com\/api(?:\/v\d+)?\/webhooks\/\d+\/[\w-]+$/.test(hook);
const url = okHook ? hook : `https://discord.com/api/v10/channels/${monitor}/messages`;
const bad = logs.find(l => l.log_error);
const warn = bad ? '⚠️ Gagal menyimpan ke sheet Logs (cek header kolom Logs): ' + String(bad.log_error).slice(0, 250) : '';

// ===== Tanpa webhook: teks polos (embed tidak bisa dikirim dengan token akun) =====
if (!okHook) {
  const lines = logs.map(l =>
    `• ${l.status === 'TERKIRIM' ? '✅' : '❌'} ${l.server} › <#${l.channel_id}> • ID: \`${l.channel_id}\` • ${String(l.tipe).toUpperCase()} • ${l.waktu} • 💬 ${l.pesan}` +
    (l.error ? '\n   ⚠️ ' + l.error : ''));
  const chunks = [];
  let cur = '🤖 **Bukti pengiriman**';
  for (const ln of lines) {
    const part = ln.slice(0, 1500);
    if ((cur + '\n\n' + part).length > 1800) { chunks.push(cur); cur = '🤖 **Bukti pengiriman (lanjutan)**'; }
    cur += '\n\n' + part;
  }
  if (warn) cur += '\n\n' + warn;
  chunks.push(cur);
  return chunks.map(content => ({ json: { url, body: { content } } }));
}

// ===== Dengan webhook: embed =====
const meta = { gm: { ico: '☀️', label: 'GM' }, gn: { ico: '🌙', label: 'GN' } };
const byType = {};
for (const l of logs) (byType[String(l.tipe).toLowerCase()] = byType[String(l.tipe).toLowerCase()] || []).push(l);
const embeds = [];
const now = new Date().toISOString();
for (const [tipe, arr] of Object.entries(byType)) {
  const m = meta[tipe] || { ico: '📨', label: tipe.toUpperCase() };
  const ok = arr.filter(l => l.status === 'TERKIRIM').length;
  const color = ok === arr.length ? 5763719 : ok === 0 ? 15548997 : 16705372;
  const pesan = [...new Set(arr.map(l => String(l.pesan)))].join(' / ');
  const fields = arr.map(l => ({
    name: `${l.status === 'TERKIRIM' ? '✅' : '❌'} ${l.server}`.slice(0, 256),
    value: (`<#${l.channel_id}>\n\`${l.channel_id}\`\n🕐 ${l.waktu}` + (l.error ? `\n⚠️ ${l.error}` : '')).slice(0, 1024),
    inline: true
  }));
  const total = Math.ceil(fields.length / 24);
  for (let i = 0; i < fields.length; i += 24) {
    embeds.push({
      title: `${m.ico} Bukti Pengiriman ${m.label}` + (total > 1 ? ` (${i / 24 + 1}/${total})` : ''),
      description: `💬 **${pesan}**`.slice(0, 2000),
      color,
      fields: fields.slice(i, i + 24),
      footer: { text: `${ok} dari ${arr.length} terkirim • GM/GN Agent` },
      timestamp: now
    });
  }
}
// batas Discord: maksimal 10 embed dan sekitar 6000 karakter per pesan
const size = (e) => (e.title || '').length + (e.description || '').length + ((e.footer && e.footer.text) || '').length +
  (e.fields || []).reduce((a, f) => a + f.name.length + f.value.length, 0);
const messages = [];
let group = [], groupSize = 0;
for (const e of embeds) {
  const s = size(e);
  if (group.length >= 10 || groupSize + s > 5500) { messages.push(group); group = []; groupSize = 0; }
  group.push(e); groupSize += s;
}
if (group.length) messages.push(group);
return messages.map((g, i) => {
  const body = { username: 'GM/GN Agent', embeds: g };
  if (i === 0 && warn) body.content = warn;
  return { json: { url, body } };
});

const cfg = {};
for (const i of $input.all()) cfg[String(i.json.key).trim()] = i.json.value;
const d = (v) => String(v ?? '').replace(/\D/g, '');
return [{ json: { monitor_channel_id: d(cfg.monitor_channel_id), admin_user_id: d(cfg.admin_user_id), last_message_id: d(cfg.last_message_id), monitor_webhook_url: String(cfg.monitor_webhook_url ?? '').trim() } }];

const ids = $input.all().map(i => i.json && i.json.id).filter(Boolean);
if (!ids.length) return [];
ids.sort((a, b) => a.length - b.length || a.localeCompare(b));
return [{ json: { key: 'last_message_id', value: 'm' + ids[ids.length - 1] } }];

const cfg = $('Siapkan Polling').first().json;
if (!cfg.last_message_id) return [];
const cmp = (a, b) => a.length - b.length || a.localeCompare(b);
const msgs = $input.all().map(i => i.json).filter(m => m && m.id);
const cmds = msgs.filter(m => m.author && String(m.author.id) === cfg.admin_user_id
    && typeof m.content === 'string' && /^!ai\s+/i.test(m.content.trim())).sort((a, b) => cmp(a.id, b.id));
return cmds.map(m => ({ json: { id: m.id, text: m.content.trim().replace(/^!ai\s+/i, '') } }));

const cfg = $('Siapkan Polling').first().json;
const hook = String(cfg.monitor_webhook_url || '').trim();
const okHook = /^https:\/\/(?:ptb\.|canary\.)?discord(?:app)?\.com\/api(?:\/v\d+)?\/webhooks\/\d+\/[\w-]+$/.test(hook);
const url = okHook ? hook : `https://discord.com/api/v10/channels/${cfg.monitor_channel_id}/messages`;
const cmds = $('Ambil Perintah').all();
const out = [];
$input.all().forEach((item, i) => {
  const j = item.json;
  const idx = (item.pairedItem && typeof item.pairedItem.item === 'number') ? item.pairedItem.item : i;
  const cmd = (cmds[idx] && cmds[idx].json) || {};
  const gagal = !(typeof j.output === 'string' && j.output);
  const text = gagal
    ? 'Perintah gagal diproses: ' + String((j.error && j.error.message) || j.error || 'tidak diketahui').slice(0, 500)
    : j.output;
  // pecah teks panjang per baris agar tiap bagian muat dalam satu embed
  const parts = [];
  let cur = '';
  for (const line of String(text).split('\n')) {
    const ln = line.slice(0, 1000);
    if ((cur + '\n' + ln).length > 3800) { parts.push(cur); cur = ''; }
    cur += (cur ? '\n' : '') + ln;
  }
  parts.push(cur);
  parts.forEach((p, k) => {
    if (okHook) {
      const embed = {
        title: gagal ? '⚠️ Perintah gagal diproses' : '🤖 Hasil perintah' + (parts.length > 1 ? ` (${k + 1}/${parts.length})` : ''),
        description: p,
        color: gagal ? 15548997 : 5793266,
        timestamp: new Date().toISOString(),
        footer: { text: 'GM/GN Agent' }
      };
      if (k === 0 && cmd.text) embed.fields = [{ name: 'Perintah', value: ('`!ai ' + cmd.text + '`').slice(0, 1024) }];
      out.push({ json: { url, body: { username: 'GM/GN Agent', embeds: [embed] } } });
    } else {
      const body = { content: ('🤖 ' + p).slice(0, 1900) };
      if (cmd.id) body.message_reference = { message_id: cmd.id };
      out.push({ json: { url, body } });
    }
  });
});
return out;
